    while (tl.sum(((lane<4)&(seen<EPOCH)).to(tl.int32),0)>0)&(~expired):
        expired=_timer()-started>TIMEOUT_NS
        seen=_sys_load(address)
    if expired:tl.atomic_or(ERROR,1)


@triton.jit
def _runtime_stage(SOURCE,WIRE,ERROR,Q:tl.constexpr,START:tl.constexpr,CHUNK:tl.constexpr,
                   PACK4:tl.constexpr,CHECK:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B);n=CHUNK*(4 if PACK4 else 1);valid=i<n
    source=(i//CHUNK)*Q+START+i%CHUNK if PACK4 else START+i
    value=tl.load(SOURCE+source,valid,0);wire=value.to(WIRE.dtype.element_ty)
    tl.store(WIRE+i,wire,valid)
    if CHECK:
        restored=wire.to(tl.float32)
        bad=tl.sum((valid&(value.to(tl.int32,bitcast=True)!=restored.to(tl.int32,bitcast=True))).to(tl.int32),0)
        if bad:tl.atomic_or(ERROR+1,1)


@triton.jit
def _runtime_peer_collective(P0,P1,P2,P3,OUT,Q:tl.constexpr,START:tl.constexpr,CHUNK:tl.constexpr,
                             RANK:tl.constexpr,KIND:tl.constexpr,OP:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B)
    if KIND=='gather' or KIND=='alltoall':
        valid=i<4*CHUNK;owner=i//CHUNK;within=i%CHUNK
        ptr=tl.where(owner==0,P0,tl.where(owner==1,P1,tl.where(owner==2,P2,P3)))
        source=within if KIND=='gather' else RANK*CHUNK+within
        value=tl.load(ptr+source,valid,0,volatile=True)
        tl.store(OUT+owner*Q+START+within,value,valid)
    else:
        valid=i<CHUNK;source=RANK*CHUNK+i if KIND=='scatter' else i
        dtype=OUT.dtype.element_ty
        a=tl.load(P0+source,valid,0,volatile=True).to(dtype)
        b=tl.load(P1+source,valid,0,volatile=True).to(dtype)
        c=tl.load(P2+source,valid,0,volatile=True).to(dtype)
        d=tl.load(P3+source,valid,0,volatile=True).to(dtype)
        if OP=='avg':a=a*.25;b=b*.25;c=c*.25;d=d*.25
        if OP=='max':value=tl.maximum(tl.maximum(a,b),tl.maximum(c,d))
        elif OP=='min':value=tl.minimum(tl.minimum(a,b),tl.minimum(c,d))
        else:value=((a+b)+c)+d
        tl.store(OUT+START+i,value,valid)


class _Channel:
    def __init__(self,name,capacity,group,error,timeout_ms):
        if capacity<4096 or capacity%16:raise ValueError('Aligned staging capacity required')
        self.name=name;self.capacity=capacity;self.rank=dist.get_rank(group);self.group=group;self.error=error
        self.epoch=0;self.barriers=0;self.calls=0;self.staged_elements=0;self.checked_elements=0;self.timeout_ms=timeout_ms
        self.pool=PeerMemory(capacity+4*32*4,group)
        self.payload=self.pool.pointer(self.rank,(capacity,),torch.uint8)
        self.peers_flags=[self.pool.pointer(r,(4*32,),torch.int32,offset_bytes=capacity) for r in range(4)]
        self.flags=self.peers_flags[self.rank]
        self.views={};self.last_event=None
        fill_(self.payload,0);fill_(self.flags,0);torch.cuda.synchronize();dist.barrier(group=group)

    def tensors(self,dtype):
        if dtype not in self.views:
            n=self.capacity//dtype.itemsize
            self.views[dtype]=[self.pool.pointer(r,(n,),dtype) for r in range(4)]
        return self.views[dtype]

    def begin(self):
        if self.last_event is not None:torch.cuda.current_stream().wait_event(self.last_event)

    def barrier(self):
        self.epoch+=1
        if self.epoch>=2**31:raise RuntimeError('Signal epoch exhausted; construct a fresh communicator')
        _runtime_peer_barrier[(1,)](*self.peers_flags,self.flags,self.error,self.epoch,self.rank,self.timeout_ms*1000000,num_warps=1)
        self.barriers+=1

    def end(self):
        self.last_event=torch.cuda.Event();self.last_event.record();self.calls+=1

    def report(self):
        return dict(capacity_bytes=self.capacity,calls=self.calls,Triton_barriers=self.barriers,staged_elements=self.staged_elements,
            checked_lossless_elements=self.checked_elements,epoch=self.epoch,
            mapped_buffer_and_signal_bytes=self.pool.size_bytes,allocation_backend='CUDA driver IPC',pool_closed=self.pool.closed)


class TritonCollectives:
    def __init__(self,*,capacities=None,group=None,timeout_ms=30000):
        group=dist.group.WORLD if group is None else group
        if dist.get_world_size(group)!=4 or dist.get_process_group_ranks(group)!=[0,1,2,3]:raise ValueError('Four canonical local ranks required')
        if torch.__version__.split('+')[0]!='2.10.0':raise ValueError('Audited Torch2.10 CUDA symmetric API required')
        device=torch.device('cuda',torch.cuda.current_device())
        self.group=group;self.closed=False;self.error=zeros((2,),device=device,dtype=torch.int32)
        if capacities is None:capacities=dict(gather=96*2**20,scatter=370*2**20,reduce=1*2**20,alltoall=8*2**20)
        if set(capacities)!={'gather','scatter','reduce','alltoall'}:raise ValueError('All four communication channels required')
        self.channels={name:_Channel(name,capacities[name],group,self.error,timeout_ms) for name in ['gather','scatter','reduce','alltoall']}

    def _run(self,kind,output,source,op='sum',lossless_bf16=False):
        if self.closed:raise RuntimeError('Closed communicator')
        if (not source.is_cuda or source.device!=output.device or not source.is_contiguous() or not output.is_contiguous()
            or source.dtype not in [torch.bfloat16,torch.float32,torch.float64,torch.int64,torch.int32]):
            raise ValueError('Supported contiguous CUDA tensors required')
        if kind=='scatter':
            if source.numel()!=4*output.numel() or output.dtype!=torch.float32:raise ValueError('Four-shard FP32 reduction output required')
            q=output.numel();pack=True
        elif kind=='alltoall':
            if source.numel()!=output.numel() or source.numel()%4 or source.dtype!=output.dtype:raise ValueError('Equal all-to-all blocks required')
            q=source.numel()//4;pack=True
        elif kind=='gather':
            if output.numel()!=4*source.numel() or output.dtype!=source.dtype:raise ValueError('Four-shard gather output required')
            q=source.numel();pack=False
        else:
            if output.shape!=source.shape or output.dtype!=source.dtype:raise ValueError('Matching all-reduce tensor required')
            q=source.numel();pack=False
        if op not in ['sum','avg','max','min'] or (op=='avg' and not output.dtype.is_floating_point):raise ValueError('Supported reduction required')
        if lossless_bf16 and (kind!='scatter' or source.dtype!=torch.float32):raise ValueError('Lossless BF16 staging is only for FP32 FSDP RS input')
        wire_dtype=torch.bfloat16 if lossless_bf16 else source.dtype
        channel=self.channels[kind];peers=channel.tensors(wire_dtype);wire=peers[dist.get_rank(self.group)]
        max_chunk=channel.capacity//wire_dtype.itemsize//(4 if pack else 1)
        channel.begin()
        for start in range(0,q,max_chunk):
            chunk=min(q-start,max_chunk);n=chunk*(4 if pack else 1)
            _runtime_stage[(triton.cdiv(n,1024),)](source,wire,self.error,q,start,chunk,pack,lossless_bf16,1024)
            channel.barrier()
            count=chunk*(4 if kind in ['gather','alltoall'] else 1)
            _runtime_peer_collective[(triton.cdiv(count,1024),)](*peers,output,q,start,chunk,dist.get_rank(self.group),kind,op,1024,enable_fp_fusion=False)
            channel.barrier();channel.staged_elements+=n
            if lossless_bf16:channel.checked_elements+=n
        channel.end()
        return output

    def all_gather(self,output,source):return self._run('gather',output,source)
    def reduce_scatter(self,output,source,op='avg',*,lossless_bf16=False):return self._run('scatter',output,source,op,lossless_bf16)
    def all_reduce(self,tensor,op='sum'):return self._run('reduce',tensor,tensor,op)
    def all_to_all(self,output,source):return self._run('alltoall',output,source)

    def barrier(self):
        if self.closed:raise RuntimeError('Closed communicator')
        channel=self.channels['reduce'];channel.begin();channel.barrier();channel.end()

    def close(self):
        if self.closed:return
        for channel in self.channels.values():channel.pool.close()
        self.closed=True

    def report(self):
        torch.cuda.synchronize();errors=self.error.cpu().tolist()
        if any(errors):raise RuntimeError(f'Triton communicator rejected: timeout={errors[0]}, lossless={errors[1]}')
        return dict(complete=True,bootstrap_backend=dist.get_backend(self.group),GPU_data_backend='Triton',GPU_barrier_backend='Triton system release/acquire',
            native_GPU_collective_calls=0,native_CUDA_barrier_calls=0,timeout_flag=errors[0],lossless_violation_flag=errors[1],
            channels={name:c.report() for name,c in self.channels.items()})

"""Explicit Triton tensor utilities needed by the whole training data path."""
import math
import torch
import triton
import triton.language as tl
from .memory import empty,raw_empty


@triton.jit
def _runtime_typed_fill(Y,N:tl.constexpr,VALUE:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B)
    value=tl.full((),VALUE,Y.dtype.element_ty)
    tl.store(Y+i,value,i<N)


def fill_(target,value):
    if not target.is_contiguous():raise ValueError('Contiguous typed fill required')
    if target.numel():_runtime_typed_fill[(triton.cdiv(target.numel(),1024),)](target,target.numel(),value,1024)
    return target


def strides(shape):
    result=[];step=1
    for size in reversed(shape):result.append(step);step*=size
    return tuple(reversed(result))


def empty_strided(shape,stride,*,device,dtype,initialize=True):
    shape=tuple(shape);stride=tuple(stride)
    if len(shape)!=len(stride) or any(s<0 for s in stride):raise ValueError('Concrete nonnegative strides required')
    span=0 if math.prod(shape)==0 else 1+sum((n-1)*s for n,s in zip(shape,stride))
    alloc=empty if initialize else raw_empty
    base=alloc((span,),device=device,dtype=dtype)
    return base.as_strided(shape,stride)


@triton.jit
def _offset(I,SHAPE:tl.constexpr,STRIDE:tl.constexpr):
    remain=I;out=tl.full(I.shape,0,tl.int64)
    for axis in tl.static_range(len(SHAPE)-1,-1,-1):
        out+=(remain%SHAPE[axis])*STRIDE[axis];remain=remain//SHAPE[axis]
    return out


@triton.jit
def _runtime_strided_copy(X,Y,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64)
    value=tl.load(X+_offset(i,SHAPE,XS),i<N,0)
    tl.store(Y+_offset(i,SHAPE,YS),value,i<N)


def copy_(target,source):
    if not target.is_cuda or not source.is_cuda or target.device!=source.device:raise ValueError('Same-device CUDA copy required')
    if source.shape!=target.shape:source=source.expand(target.shape)
    if target.numel():
        _runtime_strided_copy[(triton.cdiv(target.numel(),1024),)](source,target,target.numel(),tuple(target.shape),tuple(source.stride()),tuple(target.stride()),1024)
    return target


def clone(source,*,dtype=None,preserve=True):
    dtype=source.dtype if dtype is None else dtype
    from torch._prims_common import is_non_overlapping_and_dense
    stride=tuple(source.stride()) if preserve and is_non_overlapping_and_dense(source) else strides(source.shape)
    out=empty_strided(source.shape,stride,device=source.device,dtype=dtype)
    return copy_(out,source)


@triton.jit
def _runtime_binary(X,Y,OUT,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,OS:tl.constexpr,
                    TENSOR_Y:tl.constexpr,OP:tl.constexpr,ALPHA:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64);valid=i<N
    dtype=OUT.dtype.element_ty
    calc=tl.float32 if dtype in (tl.float16,tl.bfloat16) else dtype
    x=tl.load(X+_offset(i,SHAPE,XS),valid,0).to(calc)
    if TENSOR_Y:y=tl.load(Y+_offset(i,SHAPE,YS),valid,0).to(calc)
    else:y=tl.full((),Y,calc)
    if OP=='add':value=x+y*ALPHA
    elif OP=='sub':value=x-y*ALPHA
    elif OP=='mul':value=x*y
    elif OP=='div':value=tl.div_rn(x,y)
    elif OP=='eq':value=x==y
    elif OP=='ne':value=x!=y
    elif OP=='lt':value=x<y
    elif OP=='le':value=x<=y
    elif OP=='gt':value=x>y
    elif OP=='ge':value=x>=y
    elif OP=='and':value=x&y
    elif OP=='or':value=x|y
    else:tl.static_assert(False,'Unsupported binary operation')
    tl.store(OUT+_offset(i,SHAPE,OS),value,valid)


def binary(x,y,op,*,out=None,alpha=1):
    tensor_y=isinstance(y,torch.Tensor)
    if tensor_y and y.device.type=='cpu' and y.numel()==1:y=y.item();tensor_y=False
    if not isinstance(x,torch.Tensor) or not x.is_cuda or (tensor_y and y.device!=x.device):raise ValueError('CUDA left operand and matching right operand required')
    shape=torch.broadcast_shapes(x.shape,y.shape) if tensor_y else tuple(x.shape)
    dtype=torch.result_type(x,y)
    if op in ['eq','ne','lt','le','gt','ge']:dtype=torch.bool
    if op=='div' and not dtype.is_floating_point:dtype=torch.get_default_dtype()
    # Comparison inputs must retain their arithmetic precision rather than
    # being converted to bool before comparison.
    if op in ['eq','ne','lt','le','gt','ge']:
        return comparison(x,y,op,out=out)
    if out is None:out=empty(shape,device=x.device,dtype=dtype)
    if tuple(out.shape)!=tuple(shape):raise ValueError('Matching binary output shape required')
    xx=x.expand(shape);yy=y.expand(shape) if tensor_y else y
    if out.numel():_runtime_binary[(triton.cdiv(out.numel(),1024),)](xx,yy,out,out.numel(),tuple(shape),tuple(xx.stride()),tuple(yy.stride()) if tensor_y else (),tuple(out.stride()),tensor_y,op,alpha,1024,enable_fp_fusion=False)
    return out


@triton.jit
def _runtime_compare(X,Y,OUT,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,OS:tl.constexpr,TENSOR_Y:tl.constexpr,OP:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64);valid=i<N
    x=tl.load(X+_offset(i,SHAPE,XS),valid,0)
    if TENSOR_Y:y=tl.load(Y+_offset(i,SHAPE,YS),valid,0)
    else:y=Y
    if OP=='eq':v=x==y
    elif OP=='ne':v=x!=y
    elif OP=='lt':v=x<y
    elif OP=='le':v=x<=y
    elif OP=='gt':v=x>y
    else:v=x>=y
    tl.store(OUT+_offset(i,SHAPE,OS),v,valid)


def comparison(x,y,op,*,out=None):
    tensor_y=isinstance(y,torch.Tensor)
    shape=torch.broadcast_shapes(x.shape,y.shape) if tensor_y else tuple(x.shape)
    if out is None:out=empty(shape,device=x.device,dtype=torch.bool)
    xx=x.expand(shape);yy=y.expand(shape) if tensor_y else y
    if out.numel():_runtime_compare[(triton.cdiv(out.numel(),1024),)](xx,yy,out,out.numel(),tuple(shape),tuple(xx.stride()),tuple(yy.stride()) if tensor_y else (),tuple(out.stride()),tensor_y,op,1024)
    return out


@triton.jit
def _runtime_unary(X,Y,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,OP:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64);valid=i<N
    x=tl.load(X+_offset(i,SHAPE,XS),valid,0)
    if OP=='abs':value=tl.abs(x)
    elif OP=='neg':value=-x
    elif OP=='isfinite':value=(x==x)&(tl.abs(x)!=float('inf'))
    elif OP=='not':value=~x
    else:tl.static_assert(False,'Unsupported unary operation')
    tl.store(Y+_offset(i,SHAPE,YS),value,valid)


def unary(x,op,*,out=None):
    if out is None:out=empty(x.shape,device=x.device,dtype=torch.bool if op=='isfinite' else x.dtype)
    if out.numel():_runtime_unary[(triton.cdiv(out.numel(),1024),)](x,out,x.numel(),tuple(x.shape),tuple(x.stride()),tuple(out.stride()),op,1024)
    return out


@triton.jit
def _runtime_reduce(X,Y,N:tl.constexpr,KIND:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B);valid=i<N
    if KIND=='all':value=tl.load(X+i,valid,1);reduced=tl.min((value!=0).to(tl.int32),0)
    elif KIND=='any':value=tl.load(X+i,valid,0);reduced=tl.max((value!=0).to(tl.int32),0)
    else:
        value=tl.load(X+i,valid,0).to(Y.dtype.element_ty);reduced=tl.sum(value,0)
    tl.store(Y+tl.program_id(0),reduced)


def reduce(x,kind,*,dtype=None):
    if not x.is_contiguous():x=clone(x,preserve=False)
    if kind in ['all','any']:dtype=torch.bool;acc=torch.bool
    else:
        dtype=dtype or (x.dtype if x.dtype.is_floating_point else torch.int64)
        acc=torch.float32 if dtype in [torch.bfloat16,torch.float16] else dtype
    if not x.numel():
        out=raw_empty((),device=x.device,dtype=dtype);return fill_(out,1 if kind=='all' else 0)
    current=x
    while True:
        parts=triton.cdiv(current.numel(),1024);out=raw_empty((parts,),device=x.device,dtype=acc)
        _runtime_reduce[(parts,)](current,out,current.numel(),kind,1024)
        if parts==1:break
        current=out
    if out.dtype!=dtype:out=clone(out,dtype=dtype,preserve=False)
    return out.view(())


@triton.jit
def _runtime_chunk_cat_one(X,Y,N:tl.constexpr,LOCAL:tl.constexpr,OUT_STRIDE:tl.constexpr,START:tl.constexpr,
                           SHAPE:tl.constexpr,XS:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64);valid=i<N
    value=tl.load(X+_offset(i,SHAPE,XS),valid,0)
    tl.store(Y+(i//LOCAL)*OUT_STRIDE+START+i%LOCAL,value,valid)


def chunk_cat(tensors,dim,num_chunks,out):
    if dim!=0 or num_chunks!=4 or not out.is_contiguous():raise ValueError('Audited four-rank dim0 chunk-cat required')
    sizes=[x.numel()//4 for x in tensors]
    if any(x.ndim<1 or x.shape[0]%4 for x in tensors):raise ValueError('Uneven dim0 shard requires a separately implemented padding policy')
    width=sum(sizes)
    if out.numel()!=4*width:raise ValueError('Complete packed output size mismatch')
    start=0
    for x,n in zip(tensors,sizes):
        if x.numel():_runtime_chunk_cat_one[(triton.cdiv(x.numel(),1024),)](x,out,x.numel(),n,width,start,tuple(x.shape),tuple(x.stride()),1024)
        start+=n

"""Strict public TorchDispatchMode for runtime GPU data operations.

This is not a global monkeypatch. Known GPU operations are replaced by Triton;
unknown GPU operations fail explicitly. Views/host bookkeeping and actual
host-device DMA remain runtime operations. A real kernel trace is still
required because operations below the dispatcher can launch hidden kernels.
"""
from collections import Counter
import torch
from torch.utils._python_dispatch import TorchDispatchMode
from torch.utils._pytree import tree_flatten
from . import ops
from .memory import empty,raw_empty
from .ops import fill_


_METADATA={
    'aten::view','aten::_unsafe_view','aten::_reshape_alias','aten::as_strided',
    'aten::detach','aten::detach_','aten::alias','aten::t','aten::transpose','aten::permute',
    'aten::slice','aten::select','aten::split','aten::split_with_sizes','aten::unbind',
    'aten::squeeze','aten::squeeze_','aten::unsqueeze','aten::unsqueeze_',
    'aten::expand','aten::set_','aten::is_same_size','aten::_has_compatible_shallow_copy_type',
    'aten::lift_fresh','aten::record_stream',
}


class TritonRuntimeMode(TorchDispatchMode):
    def __init__(self):
        super().__init__();self.replaced=Counter();self.metadata=Counter();self.host_dma=Counter()

    def __torch_dispatch__(self,func,types,args=(),kwargs=None):
        kw=kwargs or {};name=func._schema.name
        flat,_=tree_flatten((args,kw));tensors=[x for x in flat if isinstance(x,torch.Tensor)]
        device=kw.get('device');requested=torch.device(device) if device is not None else None
        cuda=any(t.is_cuda for t in tensors) or (requested is not None and requested.type=='cuda')
        if not cuda:return func(*args,**kw)
        if name in _METADATA:
            self.metadata[name]+=1;return func(*args,**kw)
        if name=='aten::_local_scalar_dense':
            self.host_dma['scalar_DtoH']+=1;return func(*args,**kw)
        # Local FSDP tensors are ordinary tensors. An unexpected DTensor
        # arithmetic route must not disable this mode around native kernels.
        if any(hasattr(t,'to_local') for t in tensors):
            raise RuntimeError(f'Unimplemented DTensor GPU runtime operation: {func}')
        self.replaced[name]+=1
        if name in ['aten::empty','aten::empty_strided']:
            shape=tuple(args[0]);dtype=kw.get('dtype') or torch.get_default_dtype();device=requested or torch.get_default_device()
            stride=tuple(args[1]) if name=='aten::empty_strided' else ops.strides(shape)
            return ops.empty_strided(shape,stride,device=device,dtype=dtype)
        if name in ['aten::empty_like','aten::zeros_like','aten::ones_like']:
            source=args[0];dtype=kw.get('dtype') or source.dtype;device=requested or source.device
            if kw.get('memory_format')==torch.contiguous_format:stride=ops.strides(source.shape)
            else:
                from torch._prims_common import is_non_overlapping_and_dense
                stride=tuple(source.stride()) if is_non_overlapping_and_dense(source) else ops.strides(source.shape)
            out=ops.empty_strided(source.shape,stride,device=device,dtype=dtype,initialize=name=='aten::empty_like')
            if name!='aten::empty_like':
                # Fill the backing span, so non-contiguous dense layouts work.
                value=1 if name=='aten::ones_like' else 0
                return self._fill_strided(out,value)
            return out
        if name in ['aten::zeros','aten::ones','aten::full','aten::scalar_tensor']:
            if name=='aten::scalar_tensor':shape=();value=args[0]
            else:shape=tuple(args[0]);value=args[1] if name=='aten::full' else (1 if name=='aten::ones' else 0)
            dtype=kw.get('dtype') or (torch.get_default_dtype() if isinstance(value,float) or name in ['aten::zeros','aten::ones'] else torch.int64)
            return fill_(raw_empty(shape,device=requested or 'cuda',dtype=dtype),value)
        if name in ['aten::clone','aten::lift_fresh_copy']:return ops.clone(args[0],preserve=kw.get('memory_format')!=torch.contiguous_format)
        if name=='aten::reshape':
            try:return args[0].view(args[1])
            except RuntimeError:return ops.clone(args[0],preserve=False).view(args[1])
        if name=='aten::_to_copy':return self._to_copy(func,args[0],kw)
        if name=='aten::copy_':return self._copy(args[0],args[1],kw.get('non_blocking',False))
        if name=='aten::_foreach_copy_':
            for target,source in zip(args[0],args[1]):self._copy(target,source,kw.get('non_blocking',False))
            return None
        if name in ['aten::fill_','aten::zero_']:
            value=0 if name=='aten::zero_' else args[1]
            if isinstance(value,torch.Tensor):
                if value.is_cuda:raise RuntimeError('GPU-tensor fill scalar requires an explicit broadcast-copy implementation')
                value=value.item()
            return self._fill_strided(args[0],value)
        if name in ['aten::add','aten::add_','aten::sub','aten::sub_','aten::mul','aten::mul_','aten::div','aten::div_',
                    'aten::eq','aten::ne','aten::lt','aten::le','aten::gt','aten::ge','aten::bitwise_and','aten::bitwise_or']:
            op=name.split('::')[1].rstrip('_');op={'bitwise_and':'and','bitwise_or':'or'}.get(op,op)
            if kw.get('rounding_mode') is not None:raise RuntimeError('Explicit rounded division is not implemented')
            out=args[0] if name.endswith('_') else kw.get('out')
            return ops.binary(args[0],args[1],op,out=out,alpha=kw.get('alpha',1))
        if name in ['aten::abs','aten::neg','aten::isfinite','aten::bitwise_not']:
            return ops.unary(args[0],{'aten::bitwise_not':'not'}.get(name,name.split('::')[1]),out=kw.get('out'))
        if name in ['aten::all','aten::any','aten::sum']:
            if len(args)>1 or kw.get('dim') is not None or kw.get('keepdim',False):
                raise RuntimeError(f'Unimplemented dimension-specific GPU reduction: {func}')
            return ops.reduce(args[0],name.split('::')[1],dtype=kw.get('dtype'))
        if name in ['fsdp::all_gather_copy_in']:
            inputs,output,sizes,n,rank=args;target=output.narrow(0,n*rank,n);start=0
            for source,size in zip(inputs,sizes):
                if not source.is_contiguous():source=ops.clone(source,preserve=False)
                self._copy(target.narrow(0,start,size),source.view(-1));start+=size
            if start!=n:raise ValueError('Incomplete FSDP gather copy-in')
            return target,output
        if name in ['fsdp::split_with_sizes_copy','aten::split_with_sizes_copy']:
            source,sizes=args[:2];dim=args[2] if len(args)>2 else kw.get('dim',0);outputs=kw['out'];start=0
            for size,target in zip(sizes,outputs):ops.copy_(target,source.narrow(dim,start,size));start+=size
            if start!=source.shape[dim]:raise ValueError('Incomplete FSDP gather split')
            return None if name.startswith('fsdp::') else outputs
        if name in ['fsdp::chunk_cat','aten::_chunk_cat']:
            tensors=args[0];dim=args[1] if len(args)>1 else kw['dim'];chunks=args[2] if len(args)>2 else kw['num_chunks']
            ops.chunk_cat(tensors,dim,chunks,kw['out']);return None if name.startswith('fsdp::') else kw['out']
        raise RuntimeError(f'Unimplemented GPU runtime operation: {func}; shapes/dtypes={[(tuple(t.shape),str(t.dtype)) for t in tensors]}')

    def _fill_strided(self,target,value):
        if target.is_contiguous():return fill_(target,value)
        scalar=fill_(raw_empty((),device=target.device,dtype=target.dtype),value)
        return ops.copy_(target,scalar.expand(target.shape))

    def _copy(self,target,source,non_blocking=False):
        if target.is_cuda and source.is_cuda:return ops.copy_(target,source)
        self.host_dma['host_device_copy']+=1
        if target.is_cuda:
            # Conversion/layout on host before DMA; no CUDA arithmetic is
            # delegated to ATen's generic copy kernel.
            host=source.to(dtype=target.dtype).expand(target.shape).contiguous()
            if target.is_contiguous():target.copy_(host,non_blocking=non_blocking);return target
            temporary=raw_empty(target.shape,device=target.device,dtype=target.dtype);temporary.copy_(host,non_blocking=non_blocking)
            return ops.copy_(target,temporary)
        device=source if source.is_contiguous() and source.dtype==target.dtype else ops.clone(source,dtype=target.dtype,preserve=False)
        target.copy_(device,non_blocking=non_blocking);return target

    def _to_copy(self,func,source,kw):
        target_device=torch.device(kw.get('device') or source.device);dtype=kw.get('dtype') or source.dtype
        if source.is_cuda and target_device==source.device:
            return ops.clone(source,dtype=dtype,preserve=kw.get('memory_format')!=torch.contiguous_format)
        if source.is_cuda and target_device.type=='cuda':raise RuntimeError('Cross-device Tensor.to is not a mapped peer collective')
        self.host_dma['to_host_or_device']+=1
        if source.is_cuda:
            temporary=source if source.is_contiguous() and source.dtype==dtype else ops.clone(source,dtype=dtype,preserve=False)
            return func(temporary,**kw)
        host=source.to(dtype=dtype).contiguous()
        out=raw_empty(host.shape,device=target_device,dtype=dtype);out.copy_(host,non_blocking=kw.get('non_blocking',False));return out

    def report(self):
        return dict(strict=True,replaced_GPU_operations=dict(self.replaced),host_metadata_operations=dict(self.metadata),host_DMA_operations=dict(self.host_dma),
            scope='Host views/autograd/FSDP scheduling/driver/DMA remain. Unknown GPU data operations fail. Full real-kernel trace must additionally prove no hidden native compute.')

"""Explicit Triton tensor utilities needed by the whole training data path."""
import math
import torch
import triton
import triton.language as tl
from .memory import empty,raw_empty


@triton.jit
def _runtime_typed_fill(Y,N:tl.constexpr,VALUE:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B)
    value=tl.full((),VALUE,Y.dtype.element_ty)
    tl.store(Y+i,value,i<N)


def fill_(target,value):
    if not target.is_contiguous():raise ValueError('Contiguous typed fill required')
    if target.numel():_runtime_typed_fill[(triton.cdiv(target.numel(),1024),)](target,target.numel(),value,1024)
    return target


def strides(shape):
    result=[];step=1
    for size in reversed(shape):result.append(step);step*=size
    return tuple(reversed(result))


def empty_strided(shape,stride,*,device,dtype,initialize=True):
    shape=tuple(shape);stride=tuple(stride)
    if len(shape)!=len(stride) or any(s<0 for s in stride):raise ValueError('Concrete nonnegative strides required')
    span=0 if math.prod(shape)==0 else 1+sum((n-1)*s for n,s in zip(shape,stride))
    alloc=empty if initialize else raw_empty
    base=alloc((span,),device=device,dtype=dtype)
    return base.as_strided(shape,stride)


@triton.jit
def _offset(I,SHAPE:tl.constexpr,STRIDE:tl.constexpr):
    remain=I;out=tl.full(I.shape,0,tl.int64)
    for axis in tl.static_range(len(SHAPE)-1,-1,-1):
        out+=(remain%SHAPE[axis])*STRIDE[axis];remain=remain//SHAPE[axis]
    return out


@triton.jit
def _runtime_strided_copy(X,Y,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64)
    value=tl.load(X+_offset(i,SHAPE,XS),i<N,0)
    tl.store(Y+_offset(i,SHAPE,YS),value,i<N)


def copy_(target,source):
    if not target.is_cuda or not source.is_cuda or target.device!=source.device:raise ValueError('Same-device CUDA copy required')
    if source.shape!=target.shape:source=source.expand(target.shape)
    if target.numel():
        _runtime_strided_copy[(triton.cdiv(target.numel(),1024),)](source,target,target.numel(),tuple(target.shape),tuple(source.stride()),tuple(target.stride()),1024)
    return target


def clone(source,*,dtype=None,preserve=True):
    dtype=source.dtype if dtype is None else dtype
    from torch._prims_common import is_non_overlapping_and_dense
    stride=tuple(source.stride()) if preserve and is_non_overlapping_and_dense(source) else strides(source.shape)
    out=empty_strided(source.shape,stride,device=source.device,dtype=dtype)
    return copy_(out,source)


@triton.jit
def _runtime_binary(X,Y,OUT,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,OS:tl.constexpr,
                    TENSOR_Y:tl.constexpr,OP:tl.constexpr,ALPHA:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64);valid=i<N
    dtype:tl.constexpr=OUT.dtype.element_ty
    calc:tl.constexpr=tl.float32 if (dtype==tl.float16 or dtype==tl.bfloat16) else dtype
    x=tl.load(X+_offset(i,SHAPE,XS),valid,0).to(calc)
    if TENSOR_Y:y=tl.load(Y+_offset(i,SHAPE,YS),valid,0).to(calc)
    else:y=tl.full((),Y,calc)
    if OP=='add':value=x+y*ALPHA
    elif OP=='sub':value=x-y*ALPHA
    elif OP=='mul':value=x*y
    elif OP=='div':value=tl.div_rn(x,y)
    elif OP=='eq':value=x==y
    elif OP=='ne':value=x!=y
    elif OP=='lt':value=x<y
    elif OP=='le':value=x<=y
    elif OP=='gt':value=x>y
    elif OP=='ge':value=x>=y
    elif OP=='and':value=x&y
    elif OP=='or':value=x|y
    else:tl.static_assert(False,'Unsupported binary operation')
    tl.store(OUT+_offset(i,SHAPE,OS),value,valid)


def binary(x,y,op,*,out=None,alpha=1):
    tensor_y=isinstance(y,torch.Tensor)
    if tensor_y and y.device.type=='cpu' and y.numel()==1:y=y.item();tensor_y=False
    if not isinstance(x,torch.Tensor) or not x.is_cuda or (tensor_y and y.device!=x.device):raise ValueError('CUDA left operand and matching right operand required')
    shape=torch.broadcast_shapes(x.shape,y.shape) if tensor_y else tuple(x.shape)
    dtype=torch.result_type(x,y)
    if op in ['eq','ne','lt','le','gt','ge']:dtype=torch.bool
    if op=='div' and not dtype.is_floating_point:dtype=torch.get_default_dtype()
    # Comparison inputs must retain their arithmetic precision rather than
    # being converted to bool before comparison.
    if op in ['eq','ne','lt','le','gt','ge']:
        return comparison(x,y,op,out=out)
    if out is None:out=empty(shape,device=x.device,dtype=dtype)
    if tuple(out.shape)!=tuple(shape):raise ValueError('Matching binary output shape required')
    xx=x.expand(shape);yy=y.expand(shape) if tensor_y else y
    if out.numel():_runtime_binary[(triton.cdiv(out.numel(),1024),)](xx,yy,out,out.numel(),tuple(shape),tuple(xx.stride()),tuple(yy.stride()) if tensor_y else (),tuple(out.stride()),tensor_y,op,alpha,1024,enable_fp_fusion=False)
    return out


@triton.jit
def _runtime_compare(X,Y,OUT,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,OS:tl.constexpr,TENSOR_Y:tl.constexpr,OP:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64);valid=i<N
    x=tl.load(X+_offset(i,SHAPE,XS),valid,0)
    if TENSOR_Y:y=tl.load(Y+_offset(i,SHAPE,YS),valid,0)
    else:y=Y
    if OP=='eq':v=x==y
    elif OP=='ne':v=x!=y
    elif OP=='lt':v=x<y
    elif OP=='le':v=x<=y
    elif OP=='gt':v=x>y
    else:v=x>=y
    tl.store(OUT+_offset(i,SHAPE,OS),v,valid)


def comparison(x,y,op,*,out=None):
    tensor_y=isinstance(y,torch.Tensor)
    shape=torch.broadcast_shapes(x.shape,y.shape) if tensor_y else tuple(x.shape)
    if out is None:out=empty(shape,device=x.device,dtype=torch.bool)
    xx=x.expand(shape);yy=y.expand(shape) if tensor_y else y
    if out.numel():_runtime_compare[(triton.cdiv(out.numel(),1024),)](xx,yy,out,out.numel(),tuple(shape),tuple(xx.stride()),tuple(yy.stride()) if tensor_y else (),tuple(out.stride()),tensor_y,op,1024)
    return out


@triton.jit
def _runtime_unary(X,Y,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,OP:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64);valid=i<N
    x=tl.load(X+_offset(i,SHAPE,XS),valid,0)
    if OP=='abs':value=tl.abs(x)
    elif OP=='neg':value=-x
    elif OP=='isfinite':value=(x==x)&(tl.abs(x)!=float('inf'))
    elif OP=='not':value=~x
    else:tl.static_assert(False,'Unsupported unary operation')
    tl.store(Y+_offset(i,SHAPE,YS),value,valid)


def unary(x,op,*,out=None):
    if out is None:out=empty(x.shape,device=x.device,dtype=torch.bool if op=='isfinite' else x.dtype)
    if out.numel():_runtime_unary[(triton.cdiv(out.numel(),1024),)](x,out,x.numel(),tuple(x.shape),tuple(x.stride()),tuple(out.stride()),op,1024)
    return out


@triton.jit
def _runtime_reduce(X,Y,N:tl.constexpr,KIND:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B);valid=i<N
    if KIND=='all':value=tl.load(X+i,valid,1);reduced=tl.min((value!=0).to(tl.int32),0)
    elif KIND=='any':value=tl.load(X+i,valid,0);reduced=tl.max((value!=0).to(tl.int32),0)
    else:
        value=tl.load(X+i,valid,0).to(Y.dtype.element_ty);reduced=tl.sum(value,0)
    tl.store(Y+tl.program_id(0),reduced)


def reduce(x,kind,*,dtype=None):
    if not x.is_contiguous():x=clone(x,preserve=False)
    if kind in ['all','any']:dtype=torch.bool;acc=torch.bool
    else:
        dtype=dtype or (x.dtype if x.dtype.is_floating_point else torch.int64)
        acc=torch.float32 if dtype in [torch.bfloat16,torch.float16] else dtype
    if not x.numel():
        out=raw_empty((),device=x.device,dtype=dtype);return fill_(out,1 if kind=='all' else 0)
    current=x
    while True:
        parts=triton.cdiv(current.numel(),1024);out=raw_empty((parts,),device=x.device,dtype=acc)
        _runtime_reduce[(parts,)](current,out,current.numel(),kind,1024)
        if parts==1:break
        current=out
    if out.dtype!=dtype:out=clone(out,dtype=dtype,preserve=False)
    return out.view(())


@triton.jit
def _runtime_chunk_cat_one(X,Y,N:tl.constexpr,LOCAL:tl.constexpr,OUT_STRIDE:tl.constexpr,START:tl.constexpr,
                           SHAPE:tl.constexpr,XS:tl.constexpr,B:tl.constexpr):
    i=(tl.program_id(0)*B+tl.arange(0,B)).to(tl.int64);valid=i<N
    value=tl.load(X+_offset(i,SHAPE,XS),valid,0)
    tl.store(Y+(i//LOCAL)*OUT_STRIDE+START+i%LOCAL,value,valid)


def chunk_cat(tensors,dim,num_chunks,out):
    if dim!=0 or num_chunks!=4 or not out.is_contiguous():raise ValueError('Audited four-rank dim0 chunk-cat required')
    sizes=[x.numel()//4 for x in tensors]
    if any(x.ndim<1 or x.shape[0]%4 for x in tensors):raise ValueError('Uneven dim0 shard requires a separately implemented padding policy')
    width=sum(sizes)
    if out.numel()!=4*width:raise ValueError('Complete packed output size mismatch')
    start=0
    for x,n in zip(tensors,sizes):
        if x.numel():_runtime_chunk_cat_one[(triton.cdiv(x.numel(),1024),)](x,out,x.numel(),n,width,start,tuple(x.shape),tuple(x.stride()),1024)
        start+=n

"""Classify raw phase-wide kernels, with no framework-compute exemption."""
import hashlib,json
from collections import Counter
from qwen3_peer_v13_contract import audit_trace as previous_geometry_audit

RUNTIME_KERNELS={'_runtime_fill','_runtime_typed_fill','_runtime_strided_copy','_runtime_stage',
    '_runtime_peer_barrier','_runtime_peer_collective','_runtime_binary','_runtime_reduce',
    '_runtime_unary','_runtime_compare','_runtime_chunk_cat_one','_adamw_prepare','_adamw_update'}
MODEL_STEP=dict(_gemm=866,_gate_up=72,_native_precision_forward=72,_native_split_dq=36,
    _dq_split_reduce=36,_native_precision_dkdv=36,_native_order_delta=36,
    _attention_kv_head_reduce_kernel=36,_hf_norm_forward=145,_hf_swiglu_backward=36,
    _reduce_rows=290,_lookup=1,_zero=1,_positions=1,_tables=1,_backward=74,
    _add=144,_hf_norm_rope_forward=144,_norm_rope_backward=72,_cast=2,
    _partials=1,_local_rows=1,_pack=1,_finish=1,_means=1,_grad=1,_vocab_dw_mean=1)
MODEL_VALIDATION_BATCH=dict(_gemm=181,_gate_up=36,_native_precision_forward=36,
    _hf_norm_forward=73,_lookup=1,_positions=1,_tables=1,_add=72,_hf_norm_rope_forward=72,
    _cast=1,_partials=1,_local_rows=1,_pack=1,_finish=1,_means=1)


def audit_trace(path,*,phase,plan=None):
    raw=path.read_bytes();events=[e for e in json.loads(raw)['traceEvents'] if e.get('cat')=='kernel']
    counts=Counter(e['name'] for e in events);unknown={k:v for k,v in counts.items() if k not in RUNTIME_KERNELS and k not in MODEL_STEP}
    if phase in ['initial_step','full_step']:
        expected=MODEL_STEP;differences={name:dict(expected=n,observed=counts[name]) for name,n in expected.items() if counts[name]!=n}
        geometry=previous_geometry_audit(path,'triton_optimized',True,plan,peer=True)['model_launch_geometry_passed']
        optimizer=counts['_adamw_prepare']==counts['_adamw_update']==2
        communication=counts['_runtime_stage']>0 and counts['_runtime_peer_collective']>0 and counts['_runtime_peer_barrier']>=2*counts['_runtime_stage']
    elif phase=='validation':
        expected={name:n*32 for name,n in MODEL_VALIDATION_BATCH.items()}
        differences={name:dict(expected=n,observed=counts[name]) for name,n in expected.items() if counts[name]!=n}
        differences.update({name:dict(expected=0,observed=counts[name]) for name in set(MODEL_STEP)-set(expected) if counts[name]})
        geometry=None;optimizer=not counts['_adamw_prepare'] and not counts['_adamw_update'];communication=counts['_runtime_stage']>0 and counts['_runtime_peer_barrier']>0
    elif phase=='setup':
        differences={name:dict(expected=0,observed=counts[name]) for name in MODEL_STEP if counts[name]}
        geometry=None;optimizer=not counts['_adamw_prepare'] and not counts['_adamw_update'];communication=not counts['_runtime_peer_collective']
    else:raise ValueError('Explicit phase required')
    return dict(phase=phase,trace_sha256=hashlib.sha256(raw).hexdigest(),kernel_count=len(events),kernels=dict(counts),
        unclassified_or_native_compute=unknown,model_count_discrepancies=differences,model_launch_geometry_passed=geometry,
        optimizer_coverage_passed=optimizer,communication_coverage_passed=communication,
        passed=bool(events) and not unknown and not differences and optimizer and communication and geometry is not False,
        scope='Raw kernel events, no trace rewriting. Host CPU/driver/DMA events remain; every actual GPU compute kernel must be classified Triton. Control arms audited separately.')

"""Four local GPU collectives whose data and synchronization kernels are Triton.

CUDA Symmetric Memory provides allocation, peer mapping and CPU rendezvous.
No native NCCL/CUDA collective or CUDA barrier kernel is called. Separate
channels preserve FSDP AG/RS stream ordering without aliasing shared staging.
System-scope release stores/acquire loads use one writer per mailbox, not
unsupported remote read-modify-write atomics. Hardware correctness must be
established by the real multi-rank checks before model integration/adoption.
"""
import torch
import torch.distributed as dist
import torch.distributed._symmetric_memory as symm
import triton
import triton.language as tl
from .memory import zeros,fill_


@triton.jit
def _sys_load(P):
    return tl.inline_asm_elementwise('ld.acquire.sys.global.u32 $0, [$1];',constraints='=r,l',args=[P],dtype=tl.uint32,is_pure=False,pack=1)


@triton.jit
def _timer():
    return tl.inline_asm_elementwise('mov.u64 $0, %globaltimer;',constraints='=l',args=[],dtype=tl.uint64,is_pure=False,pack=1)


@triton.jit(do_not_specialize=['EPOCH'])
def _runtime_peer_barrier(F0,F1,F2,F3,LOCAL,ERROR,EPOCH,RANK:tl.constexpr,TIMEOUT_NS:tl.constexpr):
    lane=tl.arange(0,32)
    target=tl.where(lane==0,F0,tl.where(lane==1,F1,tl.where(lane==2,F2,F3)))+RANK*32
    tl.inline_asm_elementwise('''{
        .reg .pred active;
        setp.ne.u32 active, $3, 0;
        @active st.release.sys.global.u32 [$1], $2;
        mov.u32 $0, 0;
    }''',constraints='=r,l,r,r',args=[target,EPOCH.to(tl.uint32),(lane<4).to(tl.uint32)],dtype=tl.uint32,is_pure=False,pack=1)
    address=LOCAL+tl.minimum(lane,3)*32
    started=_timer();seen=_sys_load(address);expired=tl.full((),False,tl.int1)
    while (tl.sum(((lane<4)&(seen<EPOCH)).to(tl.int32),0)>0)&(~expired):
        expired=_timer()-started>TIMEOUT_NS
        seen=_sys_load(address)
    if expired:tl.atomic_or(ERROR,1)


@triton.jit
def _runtime_stage(SOURCE,WIRE,ERROR,Q:tl.constexpr,START:tl.constexpr,CHUNK:tl.constexpr,
                   PACK4:tl.constexpr,CHECK:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B);n=CHUNK*(4 if PACK4 else 1);valid=i<n
    source=(i//CHUNK)*Q+START+i%CHUNK if PACK4 else START+i
    value=tl.load(SOURCE+source,valid,0);wire=value.to(WIRE.dtype.element_ty)
    tl.store(WIRE+i,wire,valid)
    if CHECK:
        restored=wire.to(tl.float32)
        bad=tl.sum((valid&(value.to(tl.int32,bitcast=True)!=restored.to(tl.int32,bitcast=True))).to(tl.int32),0)
        if bad:tl.atomic_or(ERROR+1,1)


@triton.jit
def _runtime_peer_collective(P0,P1,P2,P3,OUT,Q:tl.constexpr,START:tl.constexpr,CHUNK:tl.constexpr,
                             RANK:tl.constexpr,KIND:tl.constexpr,OP:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B)
    if KIND=='gather' or KIND=='alltoall':
        valid=i<4*CHUNK;owner=i//CHUNK;within=i%CHUNK
        ptr=tl.where(owner==0,P0,tl.where(owner==1,P1,tl.where(owner==2,P2,P3)))
        source=within if KIND=='gather' else RANK*CHUNK+within
        value=tl.load(ptr+source,valid,0,volatile=True)
        tl.store(OUT+owner*Q+START+within,value,valid)
    else:
        valid=i<CHUNK;source=RANK*CHUNK+i if KIND=='scatter' else i
        dtype=OUT.dtype.element_ty
        a=tl.load(P0+source,valid,0,volatile=True).to(dtype)
        b=tl.load(P1+source,valid,0,volatile=True).to(dtype)
        c=tl.load(P2+source,valid,0,volatile=True).to(dtype)
        d=tl.load(P3+source,valid,0,volatile=True).to(dtype)
        if OP=='avg':a=a*.25;b=b*.25;c=c*.25;d=d*.25
        if OP=='max':value=tl.maximum(tl.maximum(a,b),tl.maximum(c,d))
        elif OP=='min':value=tl.minimum(tl.minimum(a,b),tl.minimum(c,d))
        else:value=((a+b)+c)+d
        tl.store(OUT+START+i,value,valid)


class _Channel:
    def __init__(self,name,capacity,group,error,timeout_ms):
        if capacity<4096 or capacity%16:raise ValueError('Aligned staging capacity required')
        self.name=name;self.capacity=capacity;self.rank=dist.get_rank(group);self.group=group;self.error=error
        self.epoch=0;self.barriers=0;self.calls=0;self.staged_elements=0;self.checked_elements=0;self.timeout_ms=timeout_ms
        self.payload=symm.empty(capacity,device='cuda',dtype=torch.uint8)
        self.payload_handle=symm.rendezvous(self.payload,group)
        self.flags=symm.empty(4*32,device='cuda',dtype=torch.int32)
        self.flags_handle=symm.rendezvous(self.flags,group)
        self.peers_flags=[self.flags_handle.get_buffer(r,(4*32,),torch.int32) for r in range(4)]
        self.views={};self.last_event=None
        fill_(self.flags,0);torch.cuda.synchronize();dist.barrier(group=group)

    def tensors(self,dtype):
        if dtype not in self.views:
            n=self.capacity//dtype.itemsize
            self.views[dtype]=[self.payload_handle.get_buffer(r,(n,),dtype) for r in range(4)]
        return self.views[dtype]

    def begin(self):
        if self.last_event is not None:torch.cuda.current_stream().wait_event(self.last_event)

    def barrier(self):
        self.epoch+=1
        if self.epoch>=2**31:raise RuntimeError('Signal epoch exhausted; construct a fresh communicator')
        _runtime_peer_barrier[(1,)](*self.peers_flags,self.flags,self.error,self.epoch,self.rank,self.timeout_ms*1000000,num_warps=1)
        self.barriers+=1

    def end(self):
        self.last_event=torch.cuda.Event();self.last_event.record();self.calls+=1

    def report(self):
        return dict(capacity_bytes=self.capacity,calls=self.calls,Triton_barriers=self.barriers,staged_elements=self.staged_elements,
            checked_lossless_elements=self.checked_elements,epoch=self.epoch,
            mapped_buffer_and_signal_bytes=self.payload_handle.buffer_size+self.payload_handle.signal_pad_size+self.flags_handle.buffer_size+self.flags_handle.signal_pad_size)


class TritonCollectives:
    def __init__(self,*,capacities=None,group=None,timeout_ms=30000):
        group=dist.group.WORLD if group is None else group
        if dist.get_world_size(group)!=4 or dist.get_process_group_ranks(group)!=[0,1,2,3]:raise ValueError('Four canonical local ranks required')
        if torch.__version__.split('+')[0]!='2.10.0':raise ValueError('Audited Torch2.10 CUDA symmetric API required')
        device=torch.device('cuda',torch.cuda.current_device());backend=symm.get_backend(device)
        if backend is None:symm.set_backend('CUDA')
        elif backend!='CUDA':raise RuntimeError('CUDA symmetric backend required')
        self.group=group;self.error=zeros((2,),device=device,dtype=torch.int32)
        if capacities is None:capacities=dict(gather=96*2**20,scatter=370*2**20,reduce=1*2**20,alltoall=8*2**20)
        if set(capacities)!={'gather','scatter','reduce','alltoall'}:raise ValueError('All four communication channels required')
        self.channels={name:_Channel(name,capacities[name],group,self.error,timeout_ms) for name in ['gather','scatter','reduce','alltoall']}

    def _run(self,kind,output,source,op='sum',lossless_bf16=False):
        if (not source.is_cuda or source.device!=output.device or not source.is_contiguous() or not output.is_contiguous()
            or source.dtype not in [torch.bfloat16,torch.float32,torch.float64,torch.int64,torch.int32]):
            raise ValueError('Supported contiguous CUDA tensors required')
        if kind=='scatter':
            if source.numel()!=4*output.numel() or output.dtype!=torch.float32:raise ValueError('Four-shard FP32 reduction output required')
            q=output.numel();pack=True
        elif kind=='alltoall':
            if source.numel()!=output.numel() or source.numel()%4 or source.dtype!=output.dtype:raise ValueError('Equal all-to-all blocks required')
            q=source.numel()//4;pack=True
        elif kind=='gather':
            if output.numel()!=4*source.numel() or output.dtype!=source.dtype:raise ValueError('Four-shard gather output required')
            q=source.numel();pack=False
        else:
            if output.shape!=source.shape or output.dtype!=source.dtype:raise ValueError('Matching all-reduce tensor required')
            q=source.numel();pack=False
        if op not in ['sum','avg','max','min'] or (op=='avg' and not output.dtype.is_floating_point):raise ValueError('Supported reduction required')
        if lossless_bf16 and (kind!='scatter' or source.dtype!=torch.float32):raise ValueError('Lossless BF16 staging is only for FP32 FSDP RS input')
        wire_dtype=torch.bfloat16 if lossless_bf16 else source.dtype
        channel=self.channels[kind];peers=channel.tensors(wire_dtype);wire=peers[dist.get_rank(self.group)]
        max_chunk=channel.capacity//wire_dtype.itemsize//(4 if pack else 1)
        channel.begin()
        for start in range(0,q,max_chunk):
            chunk=min(q-start,max_chunk);n=chunk*(4 if pack else 1)
            _runtime_stage[(triton.cdiv(n,1024),)](source,wire,self.error,q,start,chunk,pack,lossless_bf16,1024)
            channel.barrier()
            count=chunk*(4 if kind in ['gather','alltoall'] else 1)
            _runtime_peer_collective[(triton.cdiv(count,1024),)](*peers,output,q,start,chunk,dist.get_rank(self.group),kind,op,1024,enable_fp_fusion=False)
            channel.barrier();channel.staged_elements+=n
            if lossless_bf16:channel.checked_elements+=n
        channel.end()
        return output

    def all_gather(self,output,source):return self._run('gather',output,source)
    def reduce_scatter(self,output,source,op='avg',*,lossless_bf16=False):return self._run('scatter',output,source,op,lossless_bf16)
    def all_reduce(self,tensor,op='sum'):return self._run('reduce',tensor,tensor,op)
    def all_to_all(self,output,source):return self._run('alltoall',output,source)

    def barrier(self):
        channel=self.channels['reduce'];channel.begin();channel.barrier();channel.end()

    def report(self):
        torch.cuda.synchronize();errors=self.error.cpu().tolist()
        if any(errors):raise RuntimeError(f'Triton communicator rejected: timeout={errors[0]}, lossless={errors[1]}')
        return dict(complete=True,bootstrap_backend=dist.get_backend(self.group),GPU_data_backend='Triton',GPU_barrier_backend='Triton system release/acquire',
            native_GPU_collective_calls=0,native_CUDA_barrier_calls=0,timeout_flag=errors[0],lossless_violation_flag=errors[1],
            channels={name:c.report() for name,c in self.channels.items()})

"""Explicit runtime selection, peer-memory accounting and host coordination.

Full mode uses Gloo only for CPU metadata and Triton for every GPU data
collective/barrier. Native/v13/adam modes are explicitly labeled controls.
"""
from contextlib import nullcontext,contextmanager
import os,subprocess
import torch
import torch.distributed as dist
from .memory import zeros
from .dispatch import TritonRuntimeMode
from .collectives import TritonCollectives
from .fsdp import configure

CAP_GIB=41.875
RESERVE=512*2**20


def own_nvml_mib():
    rows=subprocess.check_output(['nvidia-smi','-i',str(torch.cuda.current_device()),'--query-compute-apps=pid,used_gpu_memory','--format=csv,noheader,nounits'],text=True,timeout=10)
    values=[int(f[1]) for line in rows.splitlines() if len(f:=[x.strip() for x in line.split(',')])==2 and int(f[0])==os.getpid()]
    if len(values)!=1:raise RuntimeError('Own-process NVML row unavailable')
    return values[0]


class TrainingRuntime:
    def __init__(self,kind,cpu_group):
        if kind not in ['native','v13','adam','full']:raise ValueError('Explicit runtime required')
        self.kind=kind;self.cpu_group=cpu_group;self.full=kind=='full'
        self.mode=TritonRuntimeMode() if self.full else None
        self.communication=None;self.hooks=None;self.observed_extra_bytes=0
        self.validation_cycles=[]
        if self.full:
            if os.environ.get('CUDA_VISIBLE_DEVICES') not in (None,'0,1,2,3'):raise ValueError('Identity device mapping required for accounting')
            warm=zeros((1,),device='cuda',dtype=torch.int32);torch.cuda.synchronize();del warm;torch.cuda.empty_cache()
            total=torch.cuda.get_device_properties().total_memory
            torch.cuda.set_per_process_memory_fraction((CAP_GIB*2**30-RESERVE)/total)
            before=own_nvml_mib();self.communication=TritonCollectives();torch.cuda.synchronize()
            extra=max(0,own_nvml_mib()-before)*2**20
            observed=[None]*4;dist.all_gather_object(observed,extra,group=cpu_group)
            self.observed_extra_bytes=max(observed)
            report=self.communication.report()
            mapped=sum(c['mapped_buffer_and_signal_bytes'] for c in report['channels'].values())
            if self.observed_extra_bytes>RESERVE or mapped>RESERVE:raise RuntimeError('External peer buffers exceed conservative512MiB budget')

    def scope(self):return self.mode if self.mode is not None else nullcontext()

    def bind(self,model):
        if self.full:
            self.hooks=configure(model,self.communication)
            if hasattr(model.lm_head,'communication'):model.lm_head.communication=self.communication
        elif self.kind in ['v13','adam']:
            from scripts.fsdp_peer_rs_v13 import configure as configure_v13
            self.communication=configure_v13(model)

    def reduce(self,tensor,op='sum'):
        if self.full:self.communication.all_reduce(tensor,op)
        else:dist.all_reduce(tensor,op={'sum':dist.ReduceOp.SUM,'max':dist.ReduceOp.MAX,'min':dist.ReduceOp.MIN,'avg':dist.ReduceOp.AVG}[op])
        return tensor

    def barrier(self):
        if self.full:self.communication.barrier()
        else:dist.barrier()

    @contextmanager
    def validation_memory(self):
        if not self.full and self.communication is not None:
            with self.communication.validation_memory():yield
        else:
            torch.cuda.synchronize();torch.cuda.empty_cache()
            yield
            torch.cuda.synchronize()
            self.validation_cycles.append(dict(peer_buffers_needed_for_validation_all_gather=self.full,
                torch_allocator_cap_GiB=CAP_GIB-(RESERVE/2**30 if self.full else 0),
                original_effective_cap_GiB=CAP_GIB,max_allocated_GiB=torch.cuda.max_memory_allocated()/2**30,
                max_reserved_GiB=torch.cuda.max_memory_reserved()/2**30))

    @property
    def extra_bytes(self):return RESERVE if self.kind in ['v13','adam','full'] else 0

    def report(self):
        comm=self.communication.report() if self.communication is not None else dict(mode='native')
        if self.full:
            comm.update(external_memory_budget_bytes=RESERVE,observed_extra_process_bytes=self.observed_extra_bytes,
                torch_allocator_cap_GiB=CAP_GIB-RESERVE/2**30,total_effective_cap_GiB=CAP_GIB,
                FSDP_host_units=self.hooks['units'],FSDP_AG_calls=self.hooks['all_gather'].calls,FSDP_RS_calls=self.hooks['reduce_scatter'].calls,
                validation_cycles=self.validation_cycles)
        return dict(kind=self.kind,communication=comm,strict_GPU_dispatch=self.mode.report() if self.mode is not None else None,
            CPU_bootstrap_and_metadata_backend=dist.get_backend(self.cpu_group),
            host_services='FSDP/autograd metadata, CUDA allocator/peer mappings/streams/events, CPU file IO and host-device DMA; no GPU arithmetic exemption in full mode.')

